  ["Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade."] = "收集4份烈焰之心和4份傀儡之油，然後把這些東西交給卡拉然·溫布雷。",
  ["Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity."] = "為幽暗城的馬丁‧費爾本醫生到達拉然城收集6個碎裂的哨兵核心。",
  ["Collect 6 Enchanted Coral and return them to Archmage Xylem."] = "收集6塊魔化珊瑚，然後把它們帶給大法師克希雷姆。",
  ["Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater."] = "收集8個血帽和8個格里什毒針，交給安戈洛環形山的托爾瓦·尋路者。",
  ["Collect 8 Dwarven Heirlooms from the Hall of Thanes."] = "在族長之廳收集8個矮人傳家寶。",
