  ["Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart."] = "進入黑石深淵並找到伊森迪奧斯。殺掉它，然後把你找到的資訊彙報給桑德哈特。",
  ["Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar."] = "進入怒焰裂谷，殺死饑餓者塔拉加曼，然後把他的心臟交給奧格瑪的尼爾魯·火刃。",
  ["Enter the Excavation Sites in the Wetlands and bring back Thicket Raptor Meat."] = "進入濕地的挖掘場並帶回灌木迅猛龍肉",
  ["Enter the Hall of Thanes beneath Old Ironforge and claim the Head of Durgen Dirgehammer."] = "進入舊鐵爐堡下的族長之廳，並砍下杜爾根‧戴格哈默的頭。",
  ["Enthralled Atal'ai"] = "被奴役的阿塔萊食人妖",
